/**
 * Signal Generator & File Parser Module
 * Supports client-side synthetic/biomedical generation AND
 * parsing CSV/TXT files generated by the Python NeuroKit2 backend.
 */

export class SignalGenerator {
  /**
   * Generates a realistic synthetic ECG beat cycle based on 5-Gaussian P-Q-R-S-T model
   */
  static generateECG(duration = 4.0, samplingRate = 250, heartRate = 72) {
    const totalSamples = Math.floor(duration * samplingRate);
    const samples = new Uint16Array(totalSamples);
    const beatPeriod = 60.0 / heartRate; // seconds per beat
    
    // Gaussian parameters for Lead II: amplitude (mV), width (s), time offset (s)
    const waves = [
      { a: 0.15, b: 0.035, d: -0.16 }, // P wave
      { a: -0.20, b: 0.020, d: -0.05 }, // Q wave
      { a: 1.20, b: 0.025, d: 0.00 },  // R wave (dominant peak)
      { a: -0.35, b: 0.025, d: 0.06 },  // S wave
      { a: 0.28, b: 0.070, d: 0.22 }   // T wave
    ];

    for (let i = 0; i < totalSamples; i++) {
      const t = i / samplingRate;
      const phase = (t % beatPeriod) - (beatPeriod / 2.0);
      let valMv = 0.0;

      for (const w of waves) {
        const dt = phase - w.d;
        valMv += w.a * Math.exp(-(dt * dt) / (2 * w.b * w.b));
      }

      // Add slight physiological baseline wander and minimal noise
      valMv += 0.03 * Math.sin(2 * Math.PI * 0.2 * t); // respiration wander
      valMv += (Math.random() - 0.5) * 0.015; // microvolt thermal noise

      // Map from [-0.5 mV, 1.3 mV] to 12-bit DAC [0, 4095], centered near 2048
      const dac = Math.round(2048 + (valMv / 1.5) * 1700);
      samples[i] = Math.max(0, Math.min(4095, dac));
    }

    return {
      name: `ECG_${heartRate}BPM`,
      samplingRate,
      samples: Array.from(samples),
      duration
    };
  }

  /**
   * Generates realistic Surface EMG with muscle contraction bursts
   */
  static generateEMG(duration = 4.0, samplingRate = 250) {
    const totalSamples = Math.floor(duration * samplingRate);
    const samples = new Uint16Array(totalSamples);
    
    for (let i = 0; i < totalSamples; i++) {
      const t = i / samplingRate;
      // Burst envelope activation between 1.0s-1.8s and 2.6s-3.4s
      let envelope = 0.05; // baseline resting tone
      if ((t >= 1.0 && t <= 1.8) || (t >= 2.6 && t <= 3.4)) {
        envelope = 0.85;
      }
      
      // Filtered noise simulating motor unit action potential (MUAP) summations
      const noise = (Math.random() - 0.5) + (Math.random() - 0.5);
      const emgVal = noise * envelope;

      const dac = Math.round(2048 + emgVal * 1800);
      samples[i] = Math.max(0, Math.min(4095, dac));
    }

    return {
      name: 'EMG_BURST',
      samplingRate,
      samples: Array.from(samples),
      duration
    };
  }

  /**
   * Generates calibration sine wave
   */
  static generateSine(duration = 4.0, samplingRate = 250, freq = 1.0) {
    const totalSamples = Math.floor(duration * samplingRate);
    const samples = new Uint16Array(totalSamples);

    for (let i = 0; i < totalSamples; i++) {
      const t = i / samplingRate;
      const val = Math.sin(2 * Math.PI * freq * t);
      // Scale from [-1, 1] to [200, 3895] for safe DAC swing
      const dac = Math.round(2048 + val * 1800);
      samples[i] = Math.max(0, Math.min(4095, dac));
    }

    return {
      name: `SINE_${freq}HZ`,
      samplingRate,
      samples: Array.from(samples),
      duration
    };
  }

  /**
   * Generates calibration triangle wave
   */
  static generateTriangle(duration = 4.0, samplingRate = 250, freq = 2.0) {
    const totalSamples = Math.floor(duration * samplingRate);
    const samples = new Uint16Array(totalSamples);
    const period = 1.0 / freq;

    for (let i = 0; i < totalSamples; i++) {
      const t = i / samplingRate;
      const phase = (t % period) / period;
      const val = phase < 0.5 ? (4 * phase - 1) : (3 - 4 * phase);
      const dac = Math.round(2048 + val * 1800);
      samples[i] = Math.max(0, Math.min(4095, dac));
    }

    return {
      name: `TRI_${freq}HZ`,
      samplingRate,
      samples: Array.from(samples),
      duration
    };
  }

  /**
   * Parses CSV or TXT content into an array of 12-bit samples and metadata
   */
  static parseFileContent(text, filename = 'UPLOADED.CSV') {
    const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
    let samplingRate = 250;
    let name = filename.replace(/\.[^/.]+$/, "");
    const rawValues = [];

    for (const line of lines) {
      if (line.startsWith('#')) {
        // Metadata header
        if (line.includes('SamplingRate:')) {
          const match = line.match(/SamplingRate:\s*(\d+)/i);
          if (match) samplingRate = parseInt(match[1], 10);
        } else if (line.includes('Name:')) {
          const match = line.match(/Name:\s*([\w\-]+)/i);
          if (match) name = match[1];
        }
        continue;
      }

      // Check if it's the CSV column header (e.g. index,dac_value,voltage_v)
      if (line.toLowerCase().includes('dac_value') || line.toLowerCase().includes('index')) {
        continue;
      }

      // Parse values
      if (line.includes(',')) {
        // CSV row: could be (index, dac_value, voltage) or (dac_value, ...)
        const parts = line.split(',');
        let val = NaN;
        if (parts.length >= 2) {
          // If first column is index, second is dac_value
          val = parseInt(parts[1], 10);
          if (isNaN(val)) val = parseInt(parts[0], 10);
        } else {
          val = parseInt(parts[0], 10);
        }
        if (!isNaN(val)) rawValues.push(val);
      } else {
        // Single value per line (TXT)
        const val = parseInt(line, 10);
        if (!isNaN(val)) rawValues.push(val);
      }
    }

    if (rawValues.length === 0) {
      throw new Error('No se encontraron muestras válidas en el archivo.');
    }

    // Clamp to 12-bit
    const samples = rawValues.map(v => Math.max(0, Math.min(4095, Math.round(v))));
    const duration = samples.length / samplingRate;

    return {
      name: name.toUpperCase().substring(0, 16),
      samplingRate,
      samples,
      duration
    };
  }

  /**
   * Exports sample array to CSV format string
   */
  static exportToCSV(signalData) {
    const { name, samplingRate, samples } = signalData;
    let csv = `# Name: ${name}\n`;
    csv += `# SamplingRate: ${samplingRate}\n`;
    csv += `# Samples: ${samples.length}\n`;
    csv += `# Duration_s: ${(samples.length / samplingRate).toFixed(3)}\n`;
    csv += `index,dac_value,voltage_v\n`;
    for (let i = 0; i < samples.length; i++) {
      const v = ((samples[i] / 4095.0) * 5.0).toFixed(4);
      csv += `${i},${samples[i]},${v}\n`;
    }
    return csv;
  }
}
